 dict(id='F1', claim='Y_L rest-clock number fraction at 0.03-rad unit samples 1.35-1.48e-5', verdict='CONFIRMED', codex=[x(q3, 'YL', 1)['number_fraction_codex'], x(q5, 'YL', 1)['number_fraction_codex']], own=[x(q3, 'YL', 1)['number_fraction_own'], x(q5, 'YL', 1)['number_fraction_own']], method='1-exp(-gamma tau)', label='[C]'),
